window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[107]={"id":"107","numero":107,"titre":"Item 107 — Mouvements anormaux","objectifs":[{"id":"107-1","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","contenu":"<div class=\"notion-course\"><p>Décrire le <span class=\"nc-green_bg\">mouvement</span> avant de chercher sa cause : rythme, durée, distribution, contexte de repos/action, effet des tâches et possibilité de suppression. Les circuits des <span class=\"nc-purple_bg\">ganglions de la base</span> et du <span class=\"nc-purple_bg\">cervelet</span> sont souvent impliqués, mais toutes les origines ne s’y limitent pas.</p><table><thead><tr><th><span class=\"nc-green_bg\">Mouvement</span></th><th>Description</th><th>Discriminant</th></tr></thead><tbody><tr><td><span class=\"nc-blue_bg\">Tremblement</span></td><td><span class=\"nc-red nc-bold\">Oscillation rythmique</span> autour d’une position d’équilibre.</td><td>Repos, posture, <span class=\"nc-green_bg\">mouvement</span> ou arrivée sur une cible.</td></tr><tr><td><span class=\"nc-blue_bg\">Chorée</span> / ballisme</td><td>Mouvements brefs, irréguliers, imprévisibles et non stéréotypés.</td><td>Ballisme : composante proximale de <span class=\"nc-red nc-bold\">grande amplitude</span> ; début aigu <span class=\"nc-yellow_bg\">unilatéral</span> = rechercher cause vasculaire ou métabolique.</td></tr><tr><td><span class=\"nc-blue_bg\">Dystonie</span></td><td>Contractions soutenues ou intermittentes produisant postures ou <span class=\"nc-blue_bg\">mouvements répétitifs</span> anormaux.</td><td>Souvent déclenchée/aggravée par une action ; geste antagoniste parfois améliorant.</td></tr><tr><td>Myoclonie</td><td>Secousse très brève, focale, multifocale ou généralisée.</td><td>Positive = contraction ; négative = interruption du tonus, comme l’astérixis. Origine <span class=\"nc-purple_bg\">corticale</span>, sous-<span class=\"nc-purple_bg\">corticale</span>, tronculaire ou <span class=\"nc-purple_bg\">spinale</span> possible.</td></tr><tr><td>Tic</td><td><span class=\"nc-green_bg\">Mouvement</span> ou vocalisation <span class=\"nc-red nc-bold\">bref</span>, répété, stéréotypé.</td><td>Besoin prémonitoire et suppression transitoire possibles, variables selon âge.</td></tr><tr><td>Dyskinésie</td><td>Terme descriptif large ; en pratique souvent <span class=\"nc-green_bg\">mouvement</span> choréique/dystonique lié à un médicament.</td><td>Relation à la lévodopa ou à un antagoniste dopaminergique.</td></tr></tbody></table><h4>Face, cou et geste spécialisé</h4><ul><li><span class=\"nc-orange_bg\">Torticolis spasmodique</span> : <span class=\"nc-orange_bg\">dystonie cervicale</span>. Crampe de l’écrivain : <span class=\"nc-blue_bg\">dystonie de fonction</span>. <span class=\"nc-orange_bg\">Blépharospasme</span> : <span class=\"nc-blue_bg\">dystonie</span> souvent bilatérale des orbiculaires des paupières.</li><li>Hémispasme facial : contractions unilatérales des muscles innervés par le VII, souvent liées à un conflit neurovasculaire ; ce n’est pas une <span class=\"nc-blue_bg\">dystonie focale</span>. Bilan spécialisé, parfois IRM, et <span class=\"nc-pink_bg\">toxine botulique</span> selon indication.</li><li><span class=\"nc-blue_bg\">Dystonie focale</span> : <span class=\"nc-pink_bg\">toxine botulique</span> souvent utile. Début jeune, <span class=\"nc-blue_bg\">hémidystonie</span> ou signes associés : rechercher cause secondaire, notamment <span class=\"nc-orange_bg\">Wilson</span>, et discuter un essai de lévodopa.</li><li>Toujours revoir médicaments, <span class=\"nc-orange\">toxiques</span> et antécédents familiaux ; le diagnostic positif est clinique, les examens ciblent la cause.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li></ul><p></p></details><details><summary>Situations de départ LiSA vérifiées</summary><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Mouvements_anormaux_SDD-126\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 126 · Mouvements anormaux</a><ul><li>Décrire le mouvement et son impact, rechercher iatrogénie et syndromes associés.</li><li>Orienter bilan, traitement et rééducation.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Tremblements_SDD-128\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 128 · Tremblements</a><ul><li>Distinguer types de tremblement et signes de parkinsonisme typique/atypique.</li><li>Rechercher iatrogénie, proposer traitement et suivi des complications.</li></ul></li></ul><p>Attendus consultés directement sur LiSA 2026 le 13 octobre 2026. Les arbres ATLAS sont des synthèses pédagogiques reliées aux cours complets.</p></details>","frequence":0},{"id":"107-2","rang":"A","rubrique":"Diagnostic positif","titre":"Citer les principales causes de tremblement en fonction du type sémiologique (repos ou action)","contenu":"<div class=\"notion-course\"><h4>Classer le <span class=\"nc-blue_bg\">tremblement</span> selon sa condition d’apparition</h4><table><thead><tr><th>Profil</th><th>Repères</th><th>Orientation</th></tr></thead><tbody><tr><td>Repos</td><td>Muscles relâchés, <span class=\"nc-blue nc-bold\">distal</span>, souvent <span class=\"nc-yellow_bg\">asymétrique</span>, environ 4–6 Hz ; diminue à l’action, parfois réémergent en posture.</td><td><span class=\"nc-orange_bg\">Syndrome parkinsonien</span> : chercher bradykinésie et rigidité ; <span class=\"nc-red nc-bold\">Parkinson</span> ou cause médicamenteuse/atypique.</td></tr><tr><td>Essentiel</td><td><span class=\"nc-blue_bg\">Tremblement</span> d’action <span class=\"nc-yellow_bg\">bilatéral</span> des <span class=\"nc-blue nc-bold\">membres</span> supérieurs, <span class=\"nc-blue_bg\">postural</span>/cinétique ; tête ou voix possibles, contexte familial fréquent.</td><td><span class=\"nc-red_bg\">Évolution</span> lente, retentissement pour écrire, boire, manger. L’amélioration par <span class=\"nc-green_bg\">alcool</span> n’est ni nécessaire ni un traitement à conseiller.</td></tr><tr><td><span class=\"nc-orange_bg\">Cérébelleux</span></td><td>Lent, <span class=\"nc-blue_bg\">intentionnel</span>, majoré à l’arrivée sur la cible, avec dysmétrie, dysarthrie ou ataxie.</td><td>Chercher cause cérébelleuse ; installation aiguë = imagerie urgente notamment pour <span class=\"nc-orange_bg\">AVC</span>.</td></tr><tr><td>Physiologique exagéré</td><td>Fin, <span class=\"nc-blue_bg\">postural</span>, favorisé par stress, <span class=\"nc-red_bg\">caféine</span>, <span class=\"nc-orange_bg\">hyperthyroïdie</span>, hypoglycémie ou médicament.</td><td>Contexte et bilan ciblé, notamment TSH si indiqué.</td></tr><tr><td>Fonctionnel</td><td>Variabilité, distractibilité, entraînement de fréquence par une tâche controlatérale.</td><td>Diagnostic sur signes positifs ; un terrain psychologique ou un examen normal ne suffit pas.</td></tr></tbody></table><h4>Examen pratique</h4><ol><li>Au repos véritable, mains soutenues ; sensibiliser par <span class=\"nc-red nc-bold\">calcul mental</span> et observer la marche.</li><li>Postures : bras tendus, position du bretteur ; rechercher une latence de réémergence.</li><li>Action : doigt-nez, écriture et spirale, verser de l’eau, tenir une note vocale.</li><li>Examiner bradykinésie, rigidité, <span class=\"nc-purple_bg\">cervelet</span>, marche ; analyser médicaments, <span class=\"nc-orange\">toxiques</span>, antécédents et impact fonctionnel.</li></ol><h4>Quand explorer ?</h4><ul><li><span class=\"nc-green_bg\">Tremblement essentiel</span> ou <span class=\"nc-red nc-bold\">Parkinson</span> typique : pas d’imagerie systématique. Une fréquence seule ne pose pas le diagnostic.</li><li><span class=\"nc-orange_bg\">Début brutal</span>, signes focaux, syndrome <span class=\"nc-orange_bg\">cérébelleux</span> ou asymétrie inhabituelle : imagerie selon urgence. Ataxie aiguë et terrain carentiel : traiter une suspicion de Wernicke sans attendre un dosage de B1.</li><li>Sujet jeune, surtout avant 40 ans, ou signes hépatiques/psychiatriques/<span class=\"nc-blue nc-bold\">dystoniques</span> : rechercher <span class=\"nc-orange_bg\">maladie de Wilson</span> avec <span class=\"nc-blue_bg\">bilan cuprique</span> et IRM adaptés.</li><li>DaTSCAN dans un doute précis entre déficit dopaminergique dégénératif et <span class=\"nc-green_bg\">tremblement essentiel</span>/parkinsonisme médicamenteux ; ne différencie pas tous les syndromes dégénératifs.</li></ul><h4><span class=\"nc-green_bg\">Tremblement essentiel</span> gênant</h4><p>Traitement selon retentissement : <span class=\"nc-pink nc-bold\">propranolol</span> ou <span class=\"nc-pink nc-bold\">primidone</span> sont les options usuelles de première intention, après vérification des contre-indications et titration. Autres traitements spécialisés, dont <span class=\"nc-pink nc-bold\">topiramate</span>, selon réponse et tolérance ; les <span class=\"nc-pink_bg\">benzodiazépines</span> ne sont pas une solution banale au long cours. Formes sévères résistantes : discussion spécialisée de stimulation du Vim ou de lésion ciblée, avec évaluation des bénéfices et risques.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li></ul><p></p></details>","frequence":6},{"id":"107-3","rang":"A","rubrique":"Étiologies","titre":"Citer les principaux médicaments susceptibles d'induire les différents types de mouvements anormaux","contenu":"<div class=\"notion-course\"><h4>Revue médicamenteuse systématique</h4><table><thead><tr><th><span class=\"nc-green_bg\">Mouvement</span></th><th>Principaux exemples</th></tr></thead><tbody><tr><td>Parkinsonisme</td><td>Antipsychotiques, <span class=\"nc-pink_bg\">métoclopramide</span>, <span class=\"nc-pink_bg\">métopimazine</span> ; autres médicaments possibles : flunarizine, trimétazidine, <span class=\"nc-pink_bg\">lithium</span>, <span class=\"nc-pink_bg\">valproate</span>. Ne pas tous les qualifier de <span class=\"nc-pink_bg\">neuroleptiques</span>.</td></tr><tr><td><span class=\"nc-blue_bg\">Tremblement</span> d’action</td><td>Bêta-2 mimétiques, <span class=\"nc-pink_bg\">lithium</span>, <span class=\"nc-pink_bg\">valproate</span>, antidépresseurs, <span class=\"nc-pink_bg\">amiodarone</span>, <span class=\"nc-pink_bg\">théophylline</span>, <span class=\"nc-pink_bg\">tacrolimus</span>/<span class=\"nc-pink_bg\">ciclosporine</span>.</td></tr><tr><td><span class=\"nc-blue_bg\">Dystonie</span> aiguë / dyskinésie tardive / <span class=\"nc-yellow_bg\">akathisie</span></td><td>Antagonistes dopaminergiques, dont antiémétiques. Délai d’apparition et type de <span class=\"nc-green_bg\">mouvement</span> orientent.</td></tr><tr><td>Dyskinésies choréodystoniques</td><td>Lévodopa et autres traitements dopaminergiques, relation aux doses.</td></tr><tr><td>Myoclonies</td><td>Psychotropes sérotoninergiques, opioïdes, certains antiépileptiques ou antibiotiques selon terrain ; chercher surdosage/insuffisance rénale.</td></tr><tr><td><span class=\"nc-blue_bg\">Chorée</span></td><td>Traitements dopaminergiques, certains psychotropes/antiépileptiques ; <span class=\"nc-pink nc-bold\">cocaïne</span> et amphétamines.</td></tr></tbody></table><p>Reconstituer introduction, augmentation, interaction, sevrage et élimination rénale/hépatique. Revoir le traitement avec le prescripteur ; un médicament indispensable ne s’arrête pas sans alternative. Fièvre, rigidité, dysautonomie ou altération de conscience imposent de rechercher une urgence <span class=\"nc-pink_bg\">toxique</span>, notamment syndrome malin ou sérotoninergique selon les signes.</p><p>Clozapine ou quétiapine peuvent être discutées dans certains parkinsonismes lorsque l’antipsychotique reste nécessaire ; choix spécialisé et surveillance, notamment hématologique pour la clozapine.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li></ul><p></p></details>","frequence":0},{"id":"107-4","rang":"A","rubrique":"Contenu multimédia","titre":"Reconnaître les principaux mouvements anormaux sur des cas vidéo typiques","contenu":"<div class=\"notion-course\"><p>Devant une vidéo de cas typique, l'examen est <span>purement descriptif</span>. Trois questions séquentielles structurent la reconnaissance :</p>\n    <ol>\n      <li><strong>Quel <span>type sémiologique</span> ?</strong> — <span>critères de</span> <span>rythme</span>, de <span>contrôle volontaire</span>, de <span>stéréotypie</span> et de <span>circonstances de survenue</span>.</li>\n      <li><strong>Quelle topographie ?</strong> — <span>focale</span>, <span>segmentaire</span> ou <span>généralisée</span>.</li>\n      <li><strong>Quelles particularités diagnostiques ?</strong> — <span>sensation prémonitoire</span>, fond d'hypotonie, distractibilité, aggravation posturale...</li>\n    </ol>\n\n    <table>\n      <thead><tr><th>Type</th><th>Rythme</th><th>Durée d'un épisode</th><th>Topographie typique</th><th>Contrôlable ?</th><th>Stéréotypé ?</th><th>Circonstances</th></tr></thead>\n      <tbody>\n        <tr><td><span><span class=\"nc-blue_bg\">Tremblement</span></span></td><td>Rythmique (<span>4-12 Hz</span>)</td><td>Continu tant que la condition est remplie</td><td><span class=\"nc-blue nc-bold\">Distal</span> des <span class=\"nc-blue nc-bold\">membres</span> ++</td><td>Non</td><td>Oui</td><td><span>Repos OU action</span> selon le type</td></tr>\n        <tr><td><span><span class=\"nc-blue_bg\">Chorée</span></span></td><td><span class=\"nc-red nc-bold\">Arythmique</span></td><td>Bref (<span>&lt; 1 s</span> par <span class=\"nc-green_bg\">mouvement</span>)</td><td>Variable : visage, cou, tronc, <span class=\"nc-blue nc-bold\">membres</span></td><td>Non</td><td>Non</td><td>Repos + action, fond d'hypotonie</td></tr>\n        <tr><td><span>Ballisme</span></td><td><span class=\"nc-red nc-bold\">Arythmique</span></td><td>Bref, ample</td><td>Proximal (racines des <span class=\"nc-blue nc-bold\">membres</span>)</td><td>Non</td><td>Non</td><td>Peut fluctuer</td></tr>\n        <tr><td><span><span class=\"nc-blue_bg\">Dystonie</span></span></td><td>Maintenue</td><td>Prolongé (secondes à minutes)</td><td>Variable : focale, segmentaire, généralisée</td><td>Non</td><td>Oui (stéréotypée)</td><td><span>Aggravée par le <span class=\"nc-green_bg\">mouvement</span></span> de la zone atteinte</td></tr>\n        <tr><td><span>Myoclonie</span></td><td><span class=\"nc-red nc-bold\">Arythmique</span> ou rythmique</td><td>Très bref (secousse)</td><td>Variable : focale à généralisée</td><td>Non</td><td>Non</td><td>Spontanée ou déclenchée par un stimulus</td></tr>\n        <tr><td><span>Tic</span></td><td>Variable</td><td><span class=\"nc-red nc-bold\">Bref</span></td><td>Variable, souvent céphalique</td><td>Oui (brièvement)</td><td>Oui (caricature de geste)</td><td><span>Sensation prémonitoire</span>, rebond après contrôle</td></tr>\n        <tr><td><span>Dyskinésie</span></td><td>Variable</td><td>Variable</td><td>Variable, souvent bucco-faciale et axiale</td><td>Non</td><td>Non</td><td><span>Iatrogène</span> (<span>L-DOPA</span>, <span>antipsychotiques</span>)</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"callout callout-info\">\n      <strong>Particularités vidéo des 3 entités les plus reconnaissables.</strong> <br><strong><span class=\"nc-blue_bg\">Tremblement</span> parkinsonien :</strong> <span>main au repos qui tremble pendant la marche</span> (évocateur, sans être spécifique de la <span class=\"nc-green_bg\">maladie de Parkinson</span>). <br><strong><span class=\"nc-green_bg\">Tremblement essentiel</span> :</strong> <span class=\"nc-blue_bg\">tremblement</span> <span class=\"nc-yellow_bg\">bilatéral</span> lors de l'épreuve des verres ou de la manœuvre du serment (bras tendus). <br><strong>Tic :</strong> le patient « avale » sa <span>sensation prémonitoire</span> puis relâche le tic, enchaînant parfois plusieurs tics moteurs et vocaux.\n    </div><p>Compléter l’observation par l’interrogatoire et l’examen. Les vidéos ne permettent pas à elles seules de mesurer le tonus, la sensibilité ou les réflexes. <a href=\"https://www.cen-neurologie.fr/videotheque\" target=\"_blank\" rel=\"noopener noreferrer\">S’entraîner avec la vidéothèque du CEN</a>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li><li><a href=\"https://www.cen-neurologie.fr/videotheque\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Vidéothèque de sémiologie neurologique</a></li></ul><p></p></details>","frequence":0},{"id":"107-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes cliniques de la maladie de Huntington","contenu":"<div class=\"notion-course\"><h4>Triade clinique de <span class=\"nc-red_bg\">Huntington</span></h4><p>Maladie neurodégénérative <span class=\"nc-brown_bg\">autosomique dominante</span> liée à une expansion de triplets CAG du gène HTT sur le chromosome 4. Début souvent entre 30 et 50 ans, mais formes plus <span class=\"nc-green nc-bold\">précoces</span> ou <span class=\"nc-red nc-bold\">tardives</span> possibles. Une histoire familiale absente n’exclut pas le diagnostic.</p><table><thead><tr><th>Domaine</th><th>Manifestations</th></tr></thead><tbody><tr><td>Moteur</td><td><span class=\"nc-blue_bg\">Chorée</span> progressive, impersistance motrice, troubles oculomoteurs ; puis <span class=\"nc-blue_bg\">dystonie</span>, bradykinésie/rigidité possibles. Troubles de marche, <span class=\"nc-red nc-bold\">chutes</span>, dysarthrie et dysphagie.</td></tr><tr><td>Psychiatrique</td><td><span class=\"nc-red_bg\">Dépression</span>, irritabilité, <span class=\"nc-red_bg\">anxiété</span>, <span class=\"nc-red_bg\">désinhibition</span>, changements de personnalité, parfois <span class=\"nc-red_bg\">psychose</span>. Rechercher activement risque suicidaire.</td></tr><tr><td>Cognitif</td><td>Ralentissement et <span class=\"nc-orange_bg\">syndrome dysexécutif</span> sous-cortico-frontal ; <span class=\"nc-orange_bg\">apathie</span> et <span class=\"nc-orange_bg\">anosognosie</span> fréquentes, perte d’autonomie progressive.</td></tr></tbody></table><h4>Génétique et diagnostic</h4><ul><li>La longueur de l’expansion influence l’âge de début sans prédire à elle seule le parcours individuel. Anticipation possible, surtout paternelle.</li><li>Pénétrance réduite pour 36–39 répétitions CAG ; classiquement complète à partir de 40. Le raccourci « <span class=\"nc-green_bg\">pénétrance complète</span> » ne couvre pas tous les allèles.</li><li>Confirmation moléculaire chez le <span class=\"nc-yellow_bg\">sujet symptomatique</span> après information et consentement ; conseil génétique. Chez l’apparenté asymptomatique majeur : démarche volontaire, multidisciplinaire et spécialisée, respect du droit de ne pas savoir.</li><li>IRM : atrophie striatale, notamment des noyaux caudés ; argument d’orientation, pas un substitut au diagnostic génétique.</li><li>Projet parental : discuter dans le cadre du conseil génétique les possibilités de <span class=\"nc-green_bg\">diagnostic prénatal</span> ou préimplantatoire.</li></ul><h4>Prise en charge</h4><ul><li>Coordination neurologique, psychiatrique, rééducative, nutritionnelle et sociale ; soutien des aidants, ALD, adaptation du domicile et communication.</li><li>Traitement symptomatique de la <span class=\"nc-blue_bg\">chorée</span> selon gêne : <span class=\"nc-pink_bg\">tétrabénazine</span> ou antipsychotique adapté. Surveiller <span class=\"nc-red_bg\">dépression</span>, risque suicidaire, parkinsonisme et effets indésirables.</li><li>Traiter les troubles psychiatriques, prévenir <span class=\"nc-red nc-bold\">chutes</span> et dénutrition, évaluer déglutition ; ne pas résumer le suivi à la suppression des mouvements.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3292308/fr/maladie-de-huntington-pnds\" target=\"_blank\" rel=\"noopener noreferrer\">Centre de référence · PNDS maladie de Huntington, 2021</a></li></ul><p></p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/huntington-disease","label":"Radiopaedia : Huntington disease"}]},{"id":"107-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales expressions des tics","contenu":"<div class=\"notion-course\"><p>Les tics sont des mouvements ou vocalisations soudains, brefs, récurrents et stéréotypés. Besoin prémonitoire, soulagement après réalisation et suppression transitoire sont évocateurs, mais peuvent manquer chez le jeune enfant.</p><table><thead><tr><th>Forme</th><th>Exemples</th></tr></thead><tbody><tr><td>Moteurs simples</td><td>Clignement, grimace, haussement d’épaule.</td></tr><tr><td>Moteurs complexes</td><td>Séquences gestuelles, toucher ou sauter.</td></tr><tr><td>Vocaux simples</td><td>Reniflement, raclement de gorge, son bref.</td></tr><tr><td>Vocaux complexes</td><td>Mots, écholalie ; coprolalie possible mais rare et non nécessaire au diagnostic.</td></tr></tbody></table><p>Syndrome de <span class=\"nc-red_bg\">Gilles de la Tourette</span> : plusieurs tics moteurs et au moins un tic vocal au cours de l’<span class=\"nc-red_bg\">évolution</span>, pas nécessairement simultanés ; persistance depuis plus d’un an après le début, début avant 18 ans, sans autre cause expliquant le tableau. Les tics fluctuent : ils n’ont pas à être présents en permanence.</p><ul><li>Dépister TDAH, TOC, <span class=\"nc-red_bg\">anxiété</span>, <span class=\"nc-red_bg\">dépression</span> et retentissement scolaire/social.</li><li>Présentation typique sans signe associé : diagnostic clinique, pas d’imagerie systématique.</li><li>Information et aménagements ; thérapie comportementale adaptée aux tics si gênants. Médicament spécialisé selon retentissement, notamment aripiprazole ; traiter aussi les comorbidités.</li><li>Ne pas sanctionner un enfant pour ses tics ni les assimiler à des mouvements volontaires.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li></ul><p></p></details>","frequence":1},{"id":"107-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales formes de dyskinésies","contenu":"<div class=\"notion-course\"><p><strong>Définition.</strong> Une dyskinésie est un <span class=\"nc-green_bg\">mouvement</span> anormal sans précision sémiologique stricte, mêlant le plus souvent des composantes <span><span class=\"nc-blue nc-bold\">choréiques</span></span> et/ou <span><span class=\"nc-blue nc-bold\">dystoniques</span></span>. En pratique, le terme est <strong>réservé aux mouvements induits par la <span><span class=\"nc-pink_bg\">L-DOPA</span></span> ou les <span>antipsychotiques</span></strong>.</p>\n\n    <p><strong>Dyskinésies sous <span class=\"nc-pink_bg\">L-DOPA</span></strong> (maladie de <span class=\"nc-red nc-bold\">Parkinson</span>) :</p>\n    <table>\n      <thead><tr><th>Type</th><th>Manifestations</th></tr></thead>\n      <tbody>\n        <tr><td><strong><span class=\"nc-red nc-bold\">Milieu</span> / <span class=\"nc-red nc-bold\">pic</span> de dose</strong></td><td>Mouvements involontaires plutôt <span><span class=\"nc-blue_bg\">choréiques</span> des <span class=\"nc-blue nc-bold\">membres</span> et du <span class=\"nc-blue nc-bold\">tronc</span></span></td></tr>\n        <tr><td><strong><span class=\"nc-red nc-bold\">Biphasiques</span></strong> (début ou fin de dose)</td><td>Plutôt <span><span class=\"nc-blue_bg\">dystonie</span> des <span class=\"nc-blue nc-bold\">membres</span> <span class=\"nc-blue nc-bold\">inférieurs</span>, souvent douloureuse</span></td></tr>\n      </tbody>\n    </table>\n\n    <p><strong>Dyskinésies sous antipsychotiques</strong> — trois tableaux à distinguer :</p>\n    <table>\n      <thead><tr><th>Type</th><th>Moment</th><th><span>Terrain</span></th><th>Manifestations</th></tr></thead>\n      <tbody>\n        <tr><td><strong><span class=\"nc-yellow_bg\">Akathisie</span></strong></td><td>Variable</td><td>Tout âge</td><td><span><span class=\"nc-blue nc-bold\">Difficulté à rester assis ou immobile</span></span> + impatiences (piétinement incessant). Traitement : <span><span class=\"nc-pink nc-bold\">β-bloquant non cardiosélectif</span></span>, <span><span class=\"nc-pink nc-bold\">benzodiazépine</span></span>, adaptation de la posologie. <span>Cause majeure d'inobservance et de passage à l'acte.</span></td></tr>\n        <tr><td><strong>Dyskinésies <span class=\"nc-green nc-bold\">précoces</span> / aiguës</strong></td><td>À l'initiation ou au changement de posologie</td><td><span>Sujet jeune</span> ++</td><td>Contractures musculaires céphaliques (<span><span class=\"nc-orange_bg\">crises oculogyres</span></span>, <span><span class=\"nc-orange_bg\">protraction de la langue</span></span>, <span><span class=\"nc-blue_bg\">trismus</span></span>, <span><span class=\"nc-orange_bg\">blépharospasme</span></span>) et axiales (<span><span class=\"nc-red_bg\">dystonie cervicale</span></span>, <span><span class=\"nc-red_bg\">opisthotonos</span></span>). Traitement : <span><span class=\"nc-pink_bg\">tropatépine</span> IV</span> (anticholinergique).</td></tr>\n        <tr><td><strong>Dyskinésies <span class=\"nc-red nc-bold\">tardives</span></strong></td><td>Cures <span class=\"nc-red nc-bold\">prolongées</span> ou après leur arrêt</td><td><span><span class=\"nc-pink nc-bold\">Sujet âgé</span></span></td><td><span class=\"nc-blue_bg\">Dyskinésies </span><span><span class=\"nc-blue_bg\">bucco-facio-masticatoires</span></span> (troubles de la <span class=\"nc-red nc-bold\">phonation</span>, de la déglutition, <span class=\"nc-red nc-bold\">mauvais état dentaire</span>) ± <span class=\"nc-blue nc-bold\">tronc</span> et <span class=\"nc-blue nc-bold\">membres</span>. Traitement difficile, peut persister des mois voire des années.</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"callout callout-warn\">\n      <strong>Piège ECNi classique.</strong> Jeune femme de <span>25 ans</span> sous <span><span class=\"nc-pink_bg\">halopéridol</span></span> depuis <span>48 h</span>, présentant une <span>contracture cervicale</span> et une <span>crise oculogyre</span> → <strong>dyskinésie aiguë</strong>, à traiter par <span><span class=\"nc-pink_bg\">tropatépine</span> IV</span>. Ne pas confondre avec une <span>crise d'épilepsie</span>.\n    </div>\n\n    <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 325 — Gestions des risques liés aux médicaments (<span>iatrogène</span>, erreur)</em></p><h4>Sécurité et conduite</h4><ul><li><span class=\"nc-blue_bg\">Dystonie</span> aiguë après neuroleptique/antiémétique : avis urgent et anticholinergique selon protocole ; atteinte laryngée ou respiratoire = urgence vitale.</li><li>Dyskinésie tardive : ne pas augmenter automatiquement le neuroleptique ; avis spécialisé et révision de l’exposition. Les anticholinergiques peuvent l’aggraver.</li><li><span class=\"nc-yellow_bg\">Akathisie</span> : identifier l’impatience motrice et le médicament, sans la confondre avec une agitation psychiatrique nécessitant plus de neuroleptique.</li><li>Sous lévodopa : relier les mouvements à l’horaire des prises et aux périodes ON/OFF avant adaptation.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Mouvements anormaux (107)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810da893f78e0f80f063?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Huntington</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 107, chapitre actuel</a></li></ul><p></p></details>","frequence":2}],"astuces":[{"type":"piege","titre":"Décrire avant de traiter","contenu":"<div class=\"notion-course\"><p>Rythme, circonstances, distribution et médicaments orientent le bilan.</p></div>"},{"type":"piege","titre":"Face","contenu":"<div class=\"notion-course\"><p>Hémispasme facial et <span class=\"nc-orange_bg\">blépharospasme</span> ont des mécanismes différents.</p></div>"},{"type":"piege","titre":"Fonctionnel","contenu":"<div class=\"notion-course\"><p>Le diagnostic repose sur des signes positifs, jamais sur le seul bilan normal.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Caractériser le <span class=\"nc-green_bg\">mouvement</span> et son retentissement.</li><li>Toujours rechercher iatrogénie, <span class=\"nc-orange\">toxiques</span>, antécédents familiaux et signes associés.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Traiter la cause ; adapter symptomatique et rééducation.</li><li><span class=\"nc-blue_bg\">Dystonie</span> respiratoire, déficit aigu ou confusion : urgence.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>Imagerie ciblée si début aigu, asymétrie atypique ou signes associés.</li><li>Bilan Wilson chez sujet jeune évocateur ; conseil génétique si <span class=\"nc-red_bg\">Huntington</span>.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-18-item-107-mouvements-anormaux","label":"CEN · Item 107, chapitre actuel ↗"},{"href":"https://www.cen-neurologie.fr/videotheque","label":"CEN · Vidéothèque de sémiologie neurologique ↗"},{"href":"https://www.has-sante.fr/jcms/p_3292308/fr/maladie-de-huntington-pnds","label":"Centre de référence · PNDS maladie de Huntington, 2021 ↗"},{"href":"https://livret.uness.fr/lisa/2026/Mouvements_anormaux_SDD-126","label":"LiSA · SDD 126 — Mouvements anormaux ↗"},{"href":"https://livret.uness.fr/lisa/2026/Tremblements_SDD-128","label":"LiSA · SDD 128 — Tremblements ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Début brutal ou autre signe neurologique ?","detail":"<ul><li>Dater ; rechercher déficit, ataxie, confusion ou toxique.</li></ul>","branches":[{"label":"Oui / gravité","to":"urgent"},{"label":"Non","to":"condition"}]},{"id":"urgent","kind":"urgent","label":"Explorer une cause aiguë","detail":"<ul><li>Imagerie urgente si lésion/AVC suspecté ; glycémie et bilan ciblé.</li><li>Wernicke possible : traitement sans attendre dosage.</li></ul>","branches":[]},{"id":"condition","kind":"decision","label":"Quand le tremblement apparaît-il ?","detail":"<ul><li>Observer repos, posture, mouvement et cible ; écrire/verser de l’eau.</li></ul>","branches":[{"label":"Repos avec bradykinésie/rigidité","to":"repos"},{"label":"Action sans syndrome associé","to":"action"},{"label":"Intention avec syndrome cérébelleux","to":"cerebelleux"},{"label":"Variable / distractible / discordant","to":"fonctionnel"}]},{"id":"repos","kind":"finish","label":"Rechercher un syndrome parkinsonien et sa cause","detail":"<ul><li>Médicaments, asymétrie et signes atypiques ; bilan selon question.</li></ul>","branches":[]},{"id":"action","kind":"finish","label":"Essentiel ou physiologique exagéré ?","detail":"<ul><li>Médicaments, thyroïde, caféine et contexte ; retentissement quotidien.</li><li>Pas d’imagerie systématique du profil typique ; traitement si gêne.</li></ul>","branches":[]},{"id":"cerebelleux","kind":"finish","label":"Bilan étiologique orienté","detail":"<ul><li>Cinétique, IRM, toxiques/médicaments et terrain carentiel.</li></ul>","branches":[]},{"id":"fonctionnel","kind":"uncertain","label":"Rechercher des signes positifs reproductibles","detail":"<ul><li>Distractibilité/entraînement ; ne pas conclure sur seul terrain psychologique.</li><li>Expliquer et proposer une prise en charge adaptée.</li></ul>","branches":[]}]},"cards":[{"i":"136f9670bf05","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Comment définit-on la chorée et le ballisme, et quelle est la distinction entre les deux ?","a":"<div class=\"notion-course\"><ul><li>La <strong><span class=\"nc-blue_bg\">chorée</span></strong> est un <span class=\"nc-green_bg\">mouvement</span> <span class=\"nc-red nc-bold\">brusque</span>, <span class=\"nc-red nc-bold\">aléatoire</span>, <span class=\"nc-red nc-bold\">anarchique</span>, <span class=\"nc-red nc-bold\">arythmique</span>, <span class=\"nc-red nc-bold\">sans finalité</span>, sur fond d'hypotonie, présent au repos et à l'action, touchant des territoires variés.</li><li>Le <strong>ballisme</strong> est une forme de <span class=\"nc-green_bg\">mouvement</span> choréique caractérisée par une localisation <strong>proximale</strong> (racines des <span class=\"nc-blue nc-bold\">membres</span>) et une <strong><span class=\"nc-red nc-bold\">grande amplitude</span></strong>. Il est souvent lié à une <span class=\"nc-orange_bg\">lésion vasculaire du noyau subthalamique</span> controlatéral.</li></ul></div>"},{"i":"29f9fc7f9869","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Quel est le mécanisme physiopathologique général des mouvements anormaux ?","a":"<div class=\"notion-course\"><p>Les mouvements anormaux sont généralement liés à une topographie lésionnelle du <strong><span class=\"nc-purple_bg\">cervelet</span></strong> ou des <strong><span class=\"nc-purple_bg\">ganglions de la base</span></strong> (<span class=\"nc-purple_bg\">système extrapyramidal</span>), qui sont impliqués dans la programmation des séquences motrices automatiques.</p></div>"},{"i":"9100530c2f9a","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Comment définit-on une myoclonie et quels sont ses deux types principaux ?","a":"<div class=\"notion-course\"><p>Une <strong>myoclonie</strong> est une <strong>secousse musculaire brusque</strong> d'origine centrale. On distingue <strong>deux axes</strong> : <ul><li>soit segmentaire (focale ou multifocale) vs généralisée,</li><li>soit isolée <span class=\"nc-red nc-bold\">arythmique</span> vs répétitive rythmique.</li></ul>Elle peut être <strong>positive</strong> (contraction) ou <strong>négative</strong> (résolution brutale du tonus, appelée <strong>astérixis</strong> ou <strong>flapping tremor</strong>, typique des encéphalopathies métaboliques).</p></div>"},{"i":"a5769df7ce48","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Comment définit-on un tremblement et quelles sont ses caractéristiques discriminantes ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Oscillation rythmique</span> involontaire. Décrire repos, posture et action/intention ; la fréquence aide mais ne suffit pas. Un <span class=\"nc-blue_bg\">tremblement</span> <span class=\"nc-orange_bg\">cérébelleux</span> d’action peut être lent, autour de <span class=\"nc-pink nc-bold\">3 Hz</span>.</p></div>"},{"i":"bc08233546b2","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Quelle cause de mouvements anormaux doit-on systématiquement évoquer ?","a":"<div class=\"notion-course\"><p>Devant tout <span class=\"nc-green_bg\">mouvement</span> anormal, il faut toujours évoquer une <span class=\"nc-pink_bg\">cause </span><strong><span class=\"nc-pink_bg\">iatrogène</span></strong> (notamment les <strong>neuroleptiques</strong>) ou <strong><span class=\"nc-pink_bg\">toxique</span></strong>.</p></div>"},{"i":"c7407dc2a8b1","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Quelles sont les caractéristiques d'un tic et d'une dyskinésie ?","a":"<div class=\"notion-course\"><ul><li>Un <strong>tic</strong> est un <span class=\"nc-green_bg\">mouvement</span> <span class=\"nc-red nc-bold\">soudain</span>, <span class=\"nc-red nc-bold\">bref</span>, stéréotypé, sans but (« caricature de geste »), répétitif, souvent précédé d'une sensation prémonitoire et brièvement contrôlable au prix d'une tension croissante, suivi d'un <span class=\"nc-red_bg\">phénomène de rebond</span>.</li><li>Une <strong>dyskinésie</strong> est un <span class=\"nc-green_bg\">mouvement</span> anormal sans précision stricte, mêlant des composantes <span class=\"nc-blue nc-bold\">choréiques</span> et/ou <span class=\"nc-blue nc-bold\">dystoniques</span>, un terme généralement réservé aux mouvements induits par la <strong><span class=\"nc-pink_bg\">L-DOPA</span> ou les antipsychotiques</strong>.</li></ul></div>"},{"i":"ea1a2a0e8a9c","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Comment peut-on caractériser un mouvement anormal, de manière générale ?","a":"<div class=\"notion-course\"><p>Décrire <span class=\"nc-green_bg\">mouvement</span> involontaire, rythme, distribution, durée, contexte et modulation. Chercher les autres signes neurologiques ; certains tics sont transitoirement suppressibles.</p></div>"},{"i":"f42453c327c1","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"Qu'est-ce qu'une dystonie et quelles sont les formes focales classiquement rencontrées ?","a":"<div class=\"notion-course\"><ul><li>Contractions soutenues ou intermittentes donnant postures/mouvements anormaux.</li><li>Dystonies focales : <span class=\"nc-orange_bg\">torticolis spasmodique</span>, crampe de l’écrivain, <span class=\"nc-orange_bg\">blépharospasme</span>.</li><li>L’hémispasme facial est un trouble du VII, souvent par conflit neurovasculaire ; ce n’est pas une <span class=\"nc-blue_bg\">dystonie focale</span>.</li></ul></div>"},{"i":"0b942d98540a","n":107,"o":"107-2","u":"Diagnostic positif","t":"Citer les principales causes de tremblement en fonction du type sémiologique (repos ou action)","q":"Quelles sont les caractéristiques sémiologiques du tremblement essentiel, cause fréquente de tremblement à l'action ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Tremblement</span> d’action <span class=\"nc-yellow_bg\">bilatéral</span> des <span class=\"nc-blue nc-bold\">membres</span> supérieurs, parfois tête/voix, <span class=\"nc-red_bg\">évolution</span> <span class=\"nc-red_bg nc-bold\">lente</span> ; contexte familial fréquent.</li><li>L’amélioration par <span class=\"nc-green_bg\">alcool</span> est possible mais non nécessaire, et l’<span class=\"nc-green_bg\">alcool</span> ne doit pas être conseillé comme traitement.</li></ul></div>"},{"i":"2825725ca68d","n":107,"o":"107-2","u":"Diagnostic positif","t":"Citer les principales causes de tremblement en fonction du type sémiologique (repos ou action)","q":"Quelles sont les autres principales causes de tremblement d'action, en dehors du tremblement essentiel ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-orange_bg\">Cérébelleux</span> : <span class=\"nc-blue_bg\">intentionnel</span> lent avec dysmétrie/ataxie. Physiologique exagéré : <span class=\"nc-red_bg\">caféine</span>, dysthyroïdie, hypoglycémie ou médicament.</li><li>Fonctionnel : distractibilité, variabilité et entraînement ; diagnostic sur signes positifs, pas sur seul contexte émotionnel.</li></ul></div>"},{"i":"6383d2dee082","n":107,"o":"107-2","u":"Diagnostic positif","t":"Citer les principales causes de tremblement en fonction du type sémiologique (repos ou action)","q":"Quelles sont les caractéristiques sémiologiques du tremblement parkinsonien, cause fréquente de tremblement au repos ?","a":"<div class=\"notion-course\"><p>En tant que cause fréquente de <span class=\"nc-blue_bg\">tremblement</span> au repos, le <span class=\"nc-blue_bg\">tremblement</span> parkinsonien se caractérise par :</p><ul><li>Une survenue <strong>au repos</strong>, disparaissant au <span class=\"nc-green_bg\">mouvement</span>.</li><li>Une latéralité <strong>unilatérale</strong> ou <strong><span class=\"nc-yellow_bg\">asymétrique</span></strong>.</li><li>Une fréquence <strong>lente</strong> (<strong>4-6 Hz</strong>).</li><li>Des localisations préférentielles comme les <strong><span class=\"nc-blue_bg\">membres en distalité</span></strong>, les <span class=\"nc-blue_bg\">lèvres</span>, le <span class=\"nc-blue_bg\">menton</span> ou la <span class=\"nc-blue_bg\">langue</span>, ne touchant jamais la voix ni le chef.</li><li>Une amélioration par la <strong><span class=\"nc-pink_bg\">L-DOPA</span></strong> et disparaissant au <span class=\"nc-green_bg\">sommeil</span> et au <span class=\"nc-green_bg\">mouvement</span>.</li></ul></div>"},{"i":"2d6f44e3d8b8","n":107,"o":"107-3","u":"Étiologies","t":"Citer les principaux médicaments susceptibles d'induire les différents types de mouvements anormaux","q":"Quels médicaments peuvent induire un syndrome parkinsonien iatrogène ?","a":"<div class=\"notion-course\"><p>Antipsychotiques et antagonistes dopaminergiques comme <span class=\"nc-pink_bg\">métoclopramide</span>/<span class=\"nc-pink_bg\">métopimazine</span> ; autres médicaments possibles : flunarizine, trimétazidine, <span class=\"nc-pink_bg\">lithium</span>, <span class=\"nc-pink_bg\">valproate</span>. Tous ne sont pas des <span class=\"nc-pink_bg\">neuroleptiques</span>.</p></div>"},{"i":"4bfe0278a104","n":107,"o":"107-3","u":"Étiologies","t":"Citer les principaux médicaments susceptibles d'induire les différents types de mouvements anormaux","q":"Quels médicaments sont responsables de l'exagération du tremblement physiologique ?","a":"<div class=\"notion-course\"><p>L'exagération du <span class=\"nc-blue_bg\">tremblement</span> physiologique peut être induite par :</p><ul><li>L'<strong><span class=\"nc-pink_bg\">amiodarone</span></strong>.</li><li>Le <strong><span class=\"nc-pink_bg\">salbutamol</span></strong> (et autres β2-mimétiques).</li><li>L'<strong>amitriptyline</strong> et autres antidépresseurs.</li><li>L'<strong><span class=\"nc-pink_bg\">interféron</span></strong>.</li><li>Le <strong><span class=\"nc-pink_bg\">tacrolimus</span></strong>.</li><li>La <strong><span class=\"nc-pink_bg\">ciclosporine</span></strong>.</li><li>La <strong><span class=\"nc-pink_bg\">théophylline</span></strong>.</li></ul></div>"},{"i":"b28679b4c450","n":107,"o":"107-3","u":"Étiologies","t":"Citer les principaux médicaments susceptibles d'induire les différents types de mouvements anormaux","q":"Quels sont les médicaments impliqués dans l'apparition de dyskinésies ?","a":"<div class=\"notion-course\"><p>Les dyskinésies peuvent être causées par :</p><ul><li>La <strong><span class=\"nc-pink_bg\">L-DOPA</span></strong> (dyskinésies de <span class=\"nc-red nc-bold\">milieu</span>/<span class=\"nc-red nc-bold\">pic</span> de dose ou <span class=\"nc-red nc-bold\">biphasiques</span>).</li><li>Les <strong><span class=\"nc-pink_bg\">neuroleptiques</span></strong> (<span class=\"nc-yellow_bg\">akathisie</span>, dyskinésies <span class=\"nc-green nc-bold\">précoces</span>, dyskinésies <span class=\"nc-red nc-bold\">tardives</span>).</li></ul></div>"},{"i":"ba5414b4951c","n":107,"o":"107-3","u":"Étiologies","t":"Citer les principaux médicaments susceptibles d'induire les différents types de mouvements anormaux","q":"Quels médicaments peuvent provoquer une chorée iatrogène ?","a":"<div class=\"notion-course\"><p>Les médicaments pouvant induire une <span class=\"nc-blue_bg\">chorée</span> sont :</p><ul><li>La <strong><span class=\"nc-pink nc-bold\">L-DOPA</span></strong> et les <span class=\"nc-pink nc-bold\">agonistes dopaminergiques</span>.</li><li>Les <strong>antipsychotiques</strong>.</li><li>Les <strong>antiépileptiques</strong>.</li><li>Le <strong>lithium</strong>.</li><li>Les <strong>inhibiteurs calciques</strong>.</li></ul><p>Des <span class=\"nc-orange\">toxiques</span> comme la <strong><span class=\"nc-pink nc-bold\">cocaïne</span></strong>, les <strong>amphétamines</strong> et le <strong>monoxyde de carbone</strong> peuvent également provoquer une <span class=\"nc-blue_bg\">chorée</span>.</p></div>"},{"i":"eac4334362e9","n":107,"o":"107-3","u":"Étiologies","t":"Citer les principaux médicaments susceptibles d'induire les différents types de mouvements anormaux","q":"Quels sont les médicaments susceptibles d'induire des myoclonies ?","a":"<div class=\"notion-course\"><p>Les myoclonies peuvent être induites par :</p><ul><li>Les <strong>antidépresseurs</strong> et inhibiteurs de la recapture de la sérotonine.</li><li>La <strong>L-DOPA</strong>.</li><li>Le <strong><span class=\"nc-pink_bg\">valproate</span></strong>.</li></ul></div>"},{"i":"0aa0262ef9df","n":107,"o":"107-4","u":"Contenu multimédia","t":"Reconnaître les principaux mouvements anormaux sur des cas vidéo typiques","q":"Quelles sont les particularités vidéo permettant de reconnaître un tremblement parkinsonien, un tremblement essentiel et un tic ?","a":"<div class=\"notion-course\"><ul><li>Repos <span class=\"nc-blue nc-bold\">distal</span> pendant la marche : <span class=\"nc-blue_bg\">tremblement</span> parkinsonien évocateur, non spécifique de <span class=\"nc-red nc-bold\">Parkinson</span>.</li><li><span class=\"nc-green_bg\">Tremblement essentiel</span> : posture/action, épreuve des verres et spirale. Tic : stéréotypie et suppression transitoire, besoin prémonitoire à interroger.</li></ul></div>"},{"i":"7a3e018837e7","n":107,"o":"107-4","u":"Contenu multimédia","t":"Reconnaître les principaux mouvements anormaux sur des cas vidéo typiques","q":"Quels sont les principaux critères sémiologiques à évaluer pour décrire un mouvement anormal, notamment en vidéo ?","a":"<div class=\"notion-course\"><p>Devant un <span class=\"nc-green_bg\">mouvement</span> anormal, l'évaluation sémiologique se base sur :</p><ul><li>Le <strong>type sémiologique</strong> : rythme, contrôle volontaire, stéréotypie, circonstances de survenue.</li><li>La <strong>topographie</strong> : focale, segmentaire ou généralisée.</li><li>Les <strong>particularités diagnostiques</strong> : sensation prémonitoire, fond d'hypotonie, distractibilité, aggravation posturale, etc.</li></ul></div>"},{"i":"ab5d67ff7c77","n":107,"o":"107-4","u":"Contenu multimédia","t":"Reconnaître les principaux mouvements anormaux sur des cas vidéo typiques","q":"Comment différencier sémiologiquement une myoclonie d'un ballisme et d'un tic ?","a":"<div class=\"notion-course\"><ul><li>Myoclonie : secousse très brève, parfois stimulus-sensible.</li><li>Ballisme : <span class=\"nc-green_bg\">mouvement</span> proximal ample, irrégulier, non nécessairement permanent.</li><li>Tic : <span class=\"nc-red nc-bold\">bref</span>, stéréotypé, parfois précédé d’un besoin et transitoirement suppressible.</li></ul></div>"},{"i":"c5bd097e2fc3","n":107,"o":"107-4","u":"Contenu multimédia","t":"Reconnaître les principaux mouvements anormaux sur des cas vidéo typiques","q":"Comment différencier sémiologiquement un tremblement d'une chorée et d'une dystonie ?","a":"<div class=\"notion-course\"><ul><li>Le <strong><span class=\"nc-blue_bg\">tremblement</span></strong> est <strong>rythmique</strong> (4-12 Hz), continu, non contrôlable et le plus souvent stéréotypé. Sa topographie est typiquement distale des <span class=\"nc-blue nc-bold\">membres</span> et il survient au repos ou à l'action.</li><li>La <strong><span class=\"nc-blue_bg\">chorée</span></strong> est <strong><span class=\"nc-red nc-bold\">arythmique</span></strong>, brève (&lt; 1 s par <span class=\"nc-green_bg\">mouvement</span>), non contrôlable, non stéréotypée, de topographie variable (visage, cou, <span class=\"nc-blue nc-bold\">tronc</span>, <span class=\"nc-blue nc-bold\">membres</span>), survenant au repos et à l'action, souvent sur un fond d'hypotonie.</li><li>La <strong><span class=\"nc-blue_bg\">dystonie</span></strong> est une contraction musculaire prolongée, maintenue (secondes à minutes), non contrôlable mais stéréotypée, de topographie variable (focale, segmentaire, généralisée), aggravée par le <span class=\"nc-green_bg\">mouvement</span> de la zone atteinte.</li></ul></div>"},{"i":"ecad1c07b9f6","n":107,"o":"107-4","u":"Contenu multimédia","t":"Reconnaître les principaux mouvements anormaux sur des cas vidéo typiques","q":"Qu'est-ce qu'une dyskinésie et quelles en sont les circonstances de survenue typiques ?","a":"<div class=\"notion-course\"><p>Une <strong>dyskinésie</strong> est un <span class=\"nc-green_bg\">mouvement</span> anormal de rythme et durée variables, souvent localisée au niveau bucco-facial et axial. Elle n'est pas contrôlable et non stéréotypée. Les dyskinésies sont typiquement <strong>iatrogènes</strong>, survenant par exemple après la prise de <strong><span class=\"nc-pink_bg\">L-DOPA</span></strong> ou d'<strong>antipsychotiques</strong>.</p></div>"},{"i":"30cf641e50ba","n":107,"o":"107-6","u":"Diagnostic positif","t":"Connaître les principales expressions des tics","q":"Quel est le traitement médicamenteux des tics recommandé pour les formes avec retentissement important ?","a":"<div class=\"notion-course\"><p>Le traitement médicamenteux est réservé aux formes avec un retentissement significatif et inclut la <strong><span class=\"nc-pink_bg\">rispéridone</span></strong>, l'<strong>aripiprazole</strong> et le <strong><span class=\"nc-pink_bg\">tiapride</span></strong>.</p></div>"},{"i":"3450aaf7a642","n":107,"o":"107-6","u":"Diagnostic positif","t":"Connaître les principales expressions des tics","q":"Quelles sont les trois particularités cliniques qui distinguent les tics des autres mouvements anormaux ?","a":"<div class=\"notion-course\"><ul><li>Une <strong>sensation prémonitoire</strong> : un besoin interne de bouger précédant le tic.</li><li>La capacité d'être <strong><span class=\"nc-green_bg\">contrôlable par la</span> <span class=\"nc-green_bg nc-bold\">volonté</span></strong> <span class=\"nc-green_bg\">pendant quelques minutes</span>.</li><li>Un <strong><span class=\"nc-red_bg\">phénomène de rebond</span></strong> : le tic réapparaît de façon accentuée après l'effort de contrôle, au prix d'une <span class=\"nc-red_bg\">tension interne croissante</span>.</li></ul></div>"},{"i":"60c1be49fa05","n":107,"o":"107-6","u":"Diagnostic positif","t":"Connaître les principales expressions des tics","q":"Quelle est la définition clinique d'un tic, selon l'Item 107 sur les mouvements anormaux ?","a":"<div class=\"notion-course\"><p>Un tic est un <span class=\"nc-green_bg\">mouvement</span> <strong><span class=\"nc-red nc-bold\">soudain</span></strong>, <strong><span class=\"nc-red nc-bold\">bref</span></strong>, <strong><span class=\"nc-red nc-bold\">intermittent</span></strong>, <strong>stéréotypé</strong>, <strong>sans but</strong> (ressemblant à une « caricature de geste normal »), et <strong>répétitif</strong>.</p></div>"},{"i":"ca7b657c6a2a","n":107,"o":"107-6","u":"Diagnostic positif","t":"Connaître les principales expressions des tics","q":"Quelles sont les caractéristiques de la maladie de Gilles de la Tourette ?","a":"<div class=\"notion-course\"><p>Plusieurs tics moteurs et au moins un tic vocal durant l’<span class=\"nc-red_bg\">évolution</span>, pas forcément simultanés ; plus d’un an depuis le début, début avant 18 ans, sans autre cause. TOC/TDAH fréquents ; coprolalie non nécessaire.</p></div>"},{"i":"f51e17618262","n":107,"o":"107-5","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de la maladie de Huntington","q":"Quelle triade évoque une maladie de Huntington ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Chorée</span> et autres troubles moteurs, troubles psychiatriques, déclin cognitif dysexécutif ; HTT à expansion CAG, transmission <span class=\"nc-brown_bg\">autosomique dominante</span>. Conseil génétique spécialisé.</li></ul></div>"},{"i":"16153b34fd3f","n":107,"o":"107-7","u":"Diagnostic positif","t":"Connaître les principales formes de dyskinésies","q":"Comment distinguer dystonie aiguë et dyskinésie tardive sous neuroleptique ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Dystonie</span> aiguë : contractures/crise oculogyre peu après introduction ou hausse, traitement urgent selon protocole. Tardive : mouvements bucco-facio-masticatoires après exposition prolongée, parfois persistants ; prise en charge spécialisée.</li></ul></div>"},{"i":"23272e0aa454","n":107,"o":"107-1","u":"Diagnostic positif","t":"Savoir décrire les principaux mouvements anormaux : tremblement, chorée et dyskinésies, myoclonies, tics, dystonies (crampe de l'écrivain, torticolis spasmodique), blépharospasme et hémispasme facial","q":"L’hémispasme facial est-il un blépharospasme unilatéral ?","a":"<div class=\"notion-course\"><ul><li>Non. Hémispasme = contractions dans le territoire du VII, souvent par conflit neurovasculaire. <span class=\"nc-orange_bg\">Blépharospasme</span> = <span class=\"nc-blue_bg\">dystonie</span> des orbiculaires, généralement bilatérale.</li></ul></div>"},{"i":"ae7636fa4894","n":107,"o":"107-2","u":"Diagnostic positif","t":"Citer les principales causes de tremblement en fonction du type sémiologique (repos ou action)","q":"Quels signes positifs orientent vers un tremblement fonctionnel ?","a":"<div class=\"notion-course\"><ul><li>Distractibilité, variabilité et entraînement en fréquence. Ni un bilan normal ni un antécédent psychologique ne suffisent.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181468d91f50dcafda88d?pvs=204","reviewedAt":"2026-10-13","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddVerifiedAt":"2026-10-13","sdd":[{"number":126,"title":"Mouvements anormaux","url":"https://livret.uness.fr/lisa/2026/Mouvements_anormaux_SDD-126"},{"number":128,"title":"Tremblements","url":"https://livret.uness.fr/lisa/2026/Tremblements_SDD-128"}]}};
